export const mobileControlRead=(operation:string)=>operation==='jobs.status'||registry.isRead(operation)
let authority:((device:MobileController)=>MobileController)|undefined
export function setMobileControlAuthority(resolve:(device:MobileController)=>MobileController):void{authority=resolve}
export const authorizeMobileControl=(device:MobileController,call:MobileControlCall)=>{
 if(authority)device=authority(device)
 if(call.operation==='jobs.status'){jobs.poll(device,String(call.values.id));return}
 if(call.operation==='control.result'){const original=controlPages.access(device.id,String(call.values.id));registry.authorize(device,original);authorizeMobilePlugin(device,original);return}
 registry.authorize(device,call);authorizeMobilePlugin(device,call)
}
export async function mobileControl(device:MobileController,call:MobileControlCall):Promise<unknown>{
 if(authority){const original=device;device={id:original.id,get workspaceIds(){return authority!(original).workspaceIds},get management(){return authority!(original).management}}}
 if(call.operation==='control.result'){authorizeMobileControl(device,call);return controlPages.read(device.id,String(call.values.id),Number(call.values.offset??0))}
 const execute=async()=>{
  const result=await registry.execute(device,call)
  if(call.operation==='catalog'){const {MobileControlActionSchema}=await import('@proma/protocol');for(const action of (result as {actions:MobileControlAction[]}).actions)MobileControlActionSchema.parse(action)}
  const normalized=result!==null&&typeof result==='object'&&!Array.isArray(result)?result:{result:result??null}
  return controlPages.save(device.id,call,normalized)
 }
 return call.operation==='jobs.status'?jobs.poll(device,String(call.values.id)):call.operation.startsWith('connection.')?await registry.execute(device,call):await jobs.run(device,call,execute)
}
