const mobilePluginResults=new MobileResultPages()
function mobilePluginEntry(pluginId:string,c:MobileContext){
 management(c)
 const entry=desktopPluginState().installed.find(p=>p.enabled&&p.manifest.id===pluginId)
 if(!entry||entry.manifest.runtime?.ecosystem!=='paseo')throw Error('插件未启用')
 // 任意插件RPC由插件自行访问文件。只有手机覆盖插件的全部项目授权时才传输受信任代码。
 const scopes=entry.access?.allWorkspaces?listAgentWorkspaces().map(w=>w.id):entry.access?.workspaceIds??[]
 if(!scopes.length||scopes.some(w=>!c.device.workspaceIds.includes(w)))throw Error('手机需要覆盖此插件全部项目的授权')
 return entry
}
