function authorizeMobilePlugin(device:MobileController,call:MobileControlCall):void{
 if(!call.operation.startsWith('plugins.mobile-')||call.operation==='plugins.mobile-clients')return
 let pluginId=String(call.values.pluginId??'')
 if(call.operation==='plugins.mobile-result')pluginId=mobilePluginResults.read(device.id,String(call.values.id),0).operation
 mobilePluginEntry(pluginId,{device,assertCurrent:()=>registry.authorize(authority?authority(device):device,call)})
}

